INSERT INTO guias (usuario_id, guia_imagem_url, guia_titulo, guia_conteudo, guia_tipo) VALUES
(1, 'https://images.pexels.com/photos/4503751/pexels-photo-4503751.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1',  'Guia de Cultivo para Hortelã', 'A hortelã é uma planta aromática versátil e de fácil cultivo, ideal para iniciantes. \n\n**Escolha do Local:** Prefere meia-sombra, mas tolera sol pleno em climas mais amenos. Em vasos, coloque-a em um local com boa luminosidade, mas protegida do sol forte da tarde.\n\n**Solo:** A hortelã prospera em solos ricos em matéria orgânica e que se mantenham úmidos, mas bem drenados. Uma mistura de terra vegetal, composto orgânico e um pouco de areia é ideal.\n\n**Irrigação:** Mantenha o solo constantemente úmido, mas evite encharcar. Regue a cada 1-2 dias, ou quando a camada superior do solo começar a secar. Em dias quentes, pode ser necessário regar duas vezes ao dia.\n\n**Propagação:** A hortelã é facilmente propagada por estacas. Basta cortar um galho de cerca de 10-15 cm, remover as folhas inferiores e colocar em um copo com água ou diretamente no solo úmido. As raízes surgirão em poucas semanas.\n\n**Poda:** Podar regularmente estimula o crescimento e evita que a planta fique rala. Corte os caules logo acima de um nó ou par de folhas. Use as folhas frescas em chás, pratos culinários ou drinks.\n\n**Pragas e Doenças:** A hortelã é geralmente resistente, mas pode ser atacada por pulgões ou ácaros. Use sabão de potássio ou óleos naturais para controle. Certifique-se de que a planta tenha boa circulação de ar para evitar doenças fúngicas.\n\n**Colheita:** Colha as folhas conforme a necessidade, preferencialmente pela manhã. Quanto mais você colhe, mais a planta produz.', 1),
(1, 'https://images.pexels.com/photos/3016319/pexels-photo-3016319.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1',   'Guia de Cultivo para Alface', 'A alface é uma das hortaliças mais populares para cultivar, ideal para saladas frescas. É de crescimento rápido e pode ser cultivada em vasos ou canteiros.\n\n**Escolha do Local:** A alface prefere **sol pleno** (pelo menos 4-6 horas de sol direto por dia) ou **meia-sombra** em regiões muito quentes. Proteja-a do vento forte.\n\n**Solo:** Necessita de um solo **leve, bem drenado** e **rico em matéria orgânica**. O pH ideal é entre 6,0 e 7,0. Você pode preparar o solo misturando terra vegetal, composto orgânico e um pouco de areia.\n\n**Irrigação:** Mantenha o solo consistentemente **úmido**, mas sem encharcar. Regue diariamente ou até duas vezes em dias muito quentes, especialmente nas horas mais frescas da manhã ou final da tarde. A falta de água pode deixar as folhas amargas.\n\n**Semeadura:** Pode ser feita diretamente no local definitivo ou em sementeiras. Se optar por sementeiras, transplante as mudas quando tiverem 4-6 folhas verdadeiras. Mantenha um espaçamento de 15-30 cm entre as plantas, dependendo da variedade.\n\n**Adubação:** A alface responde bem à adubação orgânica. Você pode adicionar composto ou húmus de minhoca ao solo a cada 2-3 semanas para garantir um bom desenvolvimento.\n\n**Pragas e Doenças:** Fique atento a pulgões e lesmas, que são comuns em alfaces. Use soluções naturais como água com sabão de potássio para pulgões e armadilhas para lesmas. Garanta boa ventilação para evitar doenças fúngicas.\n\n**Colheita:** A colheita pode começar entre 40 a 70 dias após a semeadura, dependendo da variedade. Você pode colher as folhas externas à medida que crescem, permitindo que a planta continue produzindo, ou colher a cabeça inteira de uma vez. Colha preferencialmente nas horas mais frescas do dia.', 1),
(1, 'https://images.pexels.com/photos/870808/pexels-photo-870808.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1',  'Guia de Cultivo para Pimenta',   'O cultivo de pimentas é recompensador, oferecendo frutos saborosos e picantes. Elas amam o calor e o sol, e com os cuidados certos, produzirão abundantemente.\n\n**Escolha do Local:** Pimentas exigem **sol pleno** (idealmente 5-8 horas de sol direto por dia) para um bom desenvolvimento e produção de frutos. Escolha um local com boa circulação de ar para evitar problemas com fungos.\n\n**Solo:** Necessitam de um solo **fértil e bem drenado**, com pH entre 6,0 e 7,0. Enriqueça o solo com bastante composto orgânico ou húmus de minhoca antes do plantio.\n\n**Irrigação:** Mantenha o solo **úmido**, mas nunca encharcado. Regue 3-4 vezes por semana, permitindo que a camada superior do solo seque um pouco entre as regas. A rega irregular pode causar estresse na planta e afetar a produção.\n\n**Semeadura e Transplante:** Pimentas podem ser semeadas em sementeiras 8-10 semanas antes do último risco de geada. Transplante as mudas para o local definitivo quando tiverem cerca de 15-20 cm de altura e o clima estiver estável. Mantenha um espaçamento de 45-60 cm entre as plantas.\n\n**Adubação:** Pimentas são "comilonas". Fertilize com um adubo rico em fósforo e potássio a cada 3-4 semanas após o início da floração, para incentivar a frutificação. Adubos orgânicos líquidos também são uma ótima opção.\n\n**Poda e Suporte:** A poda pode ser feita para estimular o crescimento lateral e a produção. Remova brotos ladrões que surgem na axila das folhas. Variedades maiores podem precisar de estacas para suporte, especialmente quando os frutos começam a pesar.\n\n**Pragas e Doenças:** Fique atento a pulgões, ácaros e moscas-brancas. Use inseticidas naturais, como óleo de neem ou sabão de potássio. Doenças fúngicas podem ser prevenidas com boa circulação de ar e evitando o excesso de umidade nas folhas.\n\n**Colheita:** A colheita pode começar entre 60 a 90 dias após o transplante, dependendo da variedade. Colha as pimentas quando atingirem o tamanho e a cor desejados. Use uma tesoura ou faca afiada para cortar o caule, evitando danificar a planta.', 1),
(1, 'https://images.pexels.com/photos/1268101/pexels-photo-1268101.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1',  'Guia de Cultivo para Cenoura', 'Cultivar cenouras pode ser um desafio gratificante, resultando em raízes crocantes e saborosas. O segredo está em preparar o solo corretamente para que elas cresçam sem impedimentos.\n\n**Escolha do Local:** A cenoura precisa de **sol pleno** (pelo menos 6 horas de sol direto por dia) para um desenvolvimento saudável. Certifique-se de que o local não tenha obstáculos subterrâneos, como pedras, que possam deformar as raízes.\n\n**Solo:** O fator mais crucial para cenouras é um solo **solto, profundo e leve**, livre de pedras e torrões. Ele deve ser bem drenado e **rico em matéria orgânica**. Uma mistura de areia, composto e terra vegetal é ideal. Evite solos muito argilosos ou compactados, pois eles impedirão o crescimento reto da raiz.\n\n**Irrigação:** Mantenha o solo **constantemente úmido**, mas nunca encharcado. Regue 2-3 vezes por semana, ajustando a frequência conforme o clima. A umidade irregular pode levar a rachaduras nas raízes.\n\n**Semeadura:** As cenouras são melhor semeadas diretamente no local definitivo, pois não gostam de transplante. Semeie as sementes finas e cubra com uma camada fina de terra. Mantenha o solo úmido até a germinação. Quando as mudas estiverem com cerca de 5 cm, faça o desbaste, deixando um espaçamento de 5-10 cm entre elas.\n\n**Adubação:** O solo já deve ser rico em matéria orgânica no plantio. Evite adubos ricos em nitrogênio em excesso, pois eles podem estimular o crescimento das folhas em detrimento das raízes. Um adubo balanceado ou rico em potássio é mais indicado se houver necessidade.\n\n**Pragas e Doenças:** As cenouras podem ser atacadas por lesmas e pulgões. A mosca da cenoura é uma praga específica que pode danificar as raízes; a rotação de culturas e a cobertura de solo podem ajudar a prevenir. Fique atento a fungos em solos mal drenados.\n\n**Colheita:** A colheita geralmente ocorre entre 70 a 100 dias após a semeadura, dependendo da variedade. Puxe uma cenoura de teste para verificar o tamanho. Colha as cenouras quando a parte superior da raiz começar a aparecer acima do solo e tiver o tamanho desejado. Colher em tempo seco facilita a retirada.', 2),
(1, 'https://images.pexels.com/photos/928251/pexels-photo-928251.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1',     'Guia de Cultivo para Alho',   'Cultivar alho é uma experiência gratificante que resulta em bulbos saborosos para a sua cozinha. Embora exija paciência, o processo é relativamente simples.\n\n**Escolha do Local:** O alho prospera em **sol pleno** (6 a 8 horas de sol direto por dia). Escolha um local no seu jardim ou em um vaso que receba bastante luz solar.\n\n**Solo:** O solo ideal para o alho deve ser **arenoso, com boa drenagem e rico em matéria orgânica**. Evite solos pesados e argilosos, que podem reter muita umidade e causar o apodrecimento dos bulbos. O pH ideal do solo varia entre 6,0 e 7,5.\n\n**Plantio:** O alho é plantado a partir de dentes individuais. Separe os dentes de um bulbo de alho grande e saudável, preferencialmente variedades específicas para plantio. Plante cada dente com a ponta para cima, a uma profundidade de cerca de 5-7 cm, e com um espaçamento de 10-15 cm entre eles. O plantio é geralmente feito no outono para colheita no verão seguinte.\n\n**Irrigação:** Mantenha o solo **úmido** durante o período de crescimento ativo, regando 1-2 vezes por semana, ou quando a camada superior do solo estiver seca. Reduza a rega quando as folhas começarem a amarelar (sinal de que o bulbo está amadurecendo), e pare completamente algumas semanas antes da colheita para evitar fungos.\n\n**Adubação:** O alho se beneficia de um solo rico em matéria orgânica. Você pode adicionar composto ou húmus de minhoca antes do plantio e novamente na primavera, quando as folhas começarem a crescer ativamente. Evite excesso de nitrogênio, que pode favorecer o crescimento foliar em detrimento do bulbo.\n\n**Cuidados Adicionais:** Remova as hastes florais (escapos) que algumas variedades de alho produzem. Isso direciona a energia da planta para o desenvolvimento do bulbo. Você pode usar os escapos jovens em pratos culinários.\n\n**Pragas e Doenças:** O alho é relativamente resistente, mas pode ser afetado por fungos (como a ferrugem) em condições de alta umidade ou solos mal drenados. A rotação de culturas ajuda a prevenir problemas. Fique atento a nematoides e tripes.\n\n**Colheita:** A colheita geralmente ocorre entre 7 a 9 meses após o plantio, quando as folhas inferiores começam a amarelar e secar, e cerca de metade das folhas da planta estão marrons. Com cuidado, desenterre os bulbos e deixe-os curar em um local seco e arejado por 2-4 semanas antes de armazenar. Isso prolonga a vida útil do alho.', 1),
(1, 'https://images.pexels.com/photos/4110467/pexels-photo-4110467.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1',   'Guia de Cultivo para Batata', 'Cultivar batatas em casa é uma ótima maneira de ter colheitas frescas e deliciosas. Apesar de exigir espaço e atenção, o resultado final vale a pena!\n\n**Escolha do Local:** Batatas precisam de **sol pleno** (pelo menos 6 horas de sol direto por dia) para um bom desenvolvimento. Escolha um local com solo que não fique encharcado.\n\n**Solo:** O solo ideal para batatas deve ser **solto, bem drenado e rico em matéria orgânica**. Evite solos muito compactados ou argilosos, pois isso dificulta o crescimento dos tubérculos. O pH ideal varia entre 5,0 e 6,5.\n\n**Plantio:** O plantio é feito a partir de "batatas-semente" (batatas com brotos). Corte as batatas-semente em pedaços, garantindo que cada pedaço tenha pelo menos um ou dois "olhos" (brotos). Deixe os pedaços secarem por 1-2 dias antes de plantar. Plante a uma profundidade de 10-15 cm, com 30-45 cm de espaçamento entre cada pedaço e 60-90 cm entre as fileiras.\n\n**Irrigação:** Mantenha o solo **úmido** durante a maior parte do ciclo de crescimento, regando cerca de 2 vezes por semana, ou quando a camada superior do solo estiver seca. A umidade consistente é crucial, especialmente durante a floração e formação dos tubérculos. Reduza a rega quando as folhas começarem a amarelar no final do ciclo.\n\n**Adubação:** Incorpore composto orgânico ou húmus de minhoca no solo antes do plantio. Durante o crescimento, você pode aplicar um fertilizante balanceado ou rico em potássio quando as plantas estiverem com cerca de 15-20 cm de altura.\n\n**Amontoamento (Hilling):** Este é um passo crucial para o cultivo de batatas. Quando as plantas atingirem cerca de 20-30 cm de altura, comece a amontoar terra ou composto ao redor da base das plantas, cobrindo os caules e parte das folhas. Repita este processo 2-3 vezes à medida que as plantas crescem. O amontoamento protege os tubérculos da luz solar (que os tornaria verdes e tóxicos) e estimula a formação de mais batatas.\n\n**Pragas e Doenças:** Fique atento a pragas como a broca da batata e a mosca-branca. Doenças fúngicas como a requeima podem ser um problema; garanta boa circulação de ar e use fungicidas orgânicos se necessário. A rotação de culturas é fundamental.\n\n**Colheita:** As batatas geralmente estão prontas para a colheita cerca de 70-120 dias após o plantio, quando a folhagem da planta começa a morrer e amarelar. Espere 2-3 semanas após a folhagem murchar completamente para colher, isso permite que a casca das batatas endureça. Desenterre os tubérculos com cuidado para não danificá-los. Deixe as batatas curarem em um local fresco e escuro por 1-2 semanas antes de armazenar em local fresco e ventilado.', 1),
(1, 'https://images.pexels.com/photos/255469/pexels-photo-255469.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1',  'Guia de Cultivo para Ervilha',   'Cultivar ervilhas em casa é gratificante, pois elas oferecem vagens doces e nutritivas que podem ser colhidas frescas. São relativamente fáceis de cuidar, especialmente em climas mais frescos.\n\n**Escolha do Local:** A ervilha prefere **sol pleno** (pelo menos 6 horas de sol direto por dia), mas em climas muito quentes, uma leve sombra durante as horas mais quentes da tarde pode ser benéfica. Certifique-se de que o local tenha boa circulação de ar.\n\n**Solo:** Necessitam de um solo **bem drenado, rico em matéria orgânica** e com pH entre 6,0 e 7,5. Solos argilosos e compactados podem prejudicar o desenvolvimento das raízes. Incorpore bastante composto ou húmus de minhoca antes do plantio.\n\n**Plantio:** As ervilhas são semeadas diretamente no solo. Plante as sementes a uma profundidade de 2-3 cm e com um espaçamento de 5-10 cm entre elas. Se for plantar em fileiras, mantenha 60-90 cm entre as fileiras. O plantio geralmente ocorre no final do inverno ou início da primavera, assim que o solo puder ser trabalhado.\n\n**Irrigação:** Mantenha o solo **úmido** de forma consistente, especialmente durante a floração e formação das vagens. Regue 1-2 vezes por semana, ou quando a camada superior do solo estiver seca. Evite molhar as folhas para prevenir doenças fúngicas.\n\n**Suporte:** A maioria das variedades de ervilha é trepadeira e necessita de **suporte** para crescer. Instale treliças, cercas ou galhos antes que as plantas comecem a se desenvolver. Isso ajuda a manter as vagens limpas e facilita a colheita.\n\n**Adubação:** O solo já deve ser enriquecido com matéria orgânica no plantio. As ervilhas, como leguminosas, fixam nitrogênio no solo, então evite adubos ricos nesse nutriente. Um fertilizante com fósforo e potássio pode ser benéfico se o solo for deficiente.\n\n**Pragas e Doenças:** Fique atento a pulgões e oídio (um fungo que causa manchas brancas nas folhas), especialmente em condições de alta umidade. Garanta boa circulação de ar e, se necessário, use fungicidas orgânicos ou inseticidas naturais como o óleo de neem.\n\n**Colheita:** A colheita geralmente começa 60-70 dias após a semeadura, dependendo da variedade. Colha as vagens quando estiverem cheias e tenras, antes que as ervilhas inchem demais. Colha regularmente para estimular a produção contínua. As ervilhas são melhores quando consumidas frescas, logo após a colheita.', 0);
